INSERT INTO `company` VALUES (1,'20250908094056','Lake Agco','Eager to find out what Kidapawan City nature has to offer, we were prodded by locals to visit Agco Lake. About 30-40 minutes drive from the city proper, our rented van from Davao City manages an uphill climb on the foothills of Mt. Apo. The road is smooth and well paved. The air immediately gets cool even on a sunny midday. A welcome sign leads you to a parking lot which was quite full when we visited. There are entries: to the left leads to the mud spring and to the right are hot and cold swimming pools. Both charge reasonable fees. The swimming pools, on the right, are crowded on weekends. There are open cottages and rooms for rent. Food is allowed inside with minimal corkage fees on bottled drinks. There are souvenir shops in the parking area. On the left area, a short walk leads to a mud spring which spikes interest because of the sulfuric steamy heat and bubbly sound created on the surface of the lake. It smells like overcooked boiled egg. You can enjoy a mudpack bath, facial or full body,, for a small donation. It seems like a good exfoliant for the skin. Some would put on the mud facial mask and rinse away on a nearby cold spring. Quite an experience!','Brgy. Ilomavis, Kidapawan City, Cotabato','09107524284','','','<iframe src=\"https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3959.930753501018!2d125.22061291116363!3d7.0174258171960435!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x32f901f9a9ff0407%3A0xd75085bf514afea7!2sLake%20Agco!5e0!3m2!1sen!2sph!4v1757989893826!5m2!1sen!2sph\" width=\"600\" height=\"450\" style=\"border:0;\" allowfullscreen=\"\" loading=\"lazy\" referrerpolicy=\"no-referrer-when-downgrade\"></iframe>','Approved','2025-09-08','09:55:00');
/*!40000 ALTER TABLE `company` ENABLE KEYS */;
UNLOCK TABLES;

